async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  message: {type: 'list_sessions'; limit?: number; before?: {updatedAt: string | number; sessionId: string}},
  sessionStore?: SessionStore
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }

  try {
    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
    const sessions = summaries.map(summary => ({
      sessionId: summary.sessionId,
      createdAt: summary.createdAt instanceof Date ? summary.createdAt.toISOString() : summary.createdAt,
      updatedAt: summary.updatedAt instanceof Date ? summary.updatedAt.toISOString() : summary.updatedAt,
      entryCount: summary.entryCount,
    }));
    sendJson(ws, {type: 'session_list', sessions});
  } catch (error) {
    log.error('ws', 'listFor failed', {
      userId: session.userId,
      error: error instanceof Error ? error.message : 'Unknown error',
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
}

